module sum_module (
    input KAPWR,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output [1:0] sum
);

    sky130_fd_sc_lp__decapkapwr_3 base (
        .KAPWR(KAPWR),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

    assign sum = VPWR + VPB;



// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (VNB == 1'b1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
end
// HT_END
endmodule
